Arguments: {"title":"Navigate to CSRankings and extract top institutions","cwd":null,"code":"const tabId = 787783793;
await tool.navigate({ tabId, url: "https://csrankings.org/#/index?all&us" });
await tool.wait_for({ tabId, condition: "selector_visible", value: "#ranking", timeout_ms: 15000 });

// Let's get the list of top 25 institutions from csrankings
const top25 = await browserjs(tabId, () => {
  const rows = Array.from(document.querySelectorAll("#ranking tbody tr"));
  const results = [];
  for (const r of rows) {
    const nameEl = r.querySelector("span[onclick*='rankings']");
    if (nameEl) {
      results.push(nameEl.textContent.trim());
    } else {
      // try finding institution name
      const cells = Array.from(r.querySelectorAll("td"));
      if (cells.length > 1) {
        const text = cells[1]?.textContent?.trim();
        if (text) results.push(text);
      }
    }
  }
  return results.slice(0, 30);
});

console.log("Top institutions:", top25);
"}
